// Paste your Discord webhook URL below (Server Settings -> Integrations ->
// Webhooks -> New Webhook -> Copy URL). Empty = notifications disabled.
const WEBHOOK = '';
if (!WEBHOOK) return [];
const SITE = 'https://n8n-chi-azure.vercel.app';
const sd = $getWorkflowStaticData('global');
sd.sent = sd.sent || {};
const now = Date.now();
for (const k of Object.keys(sd.sent)) {
  if (now - sd.sent[k] > 14 * 24 * 3600 * 1000) delete sd.sent[k];
}
const items = $input.all().map(i => i.json).filter(j => j && j.id && j.fields);
const msgs = [];
const mark = (key) => { if (sd.sent[key]) return false; sd.sent[key] = now; return true; };

// Scripts awaiting review
for (const j of items) {
  const f = j.fields;
  if (f['Script Content'] !== undefined && f['Status'] === 'awaiting_approval') {
    if (mark('script:' + j.id)) {
      msgs.push('📜 **Script gata de review:** ' + (f['Script Title'] || j.id) + '\n' + SITE);
    }
  }
}

// Scenes awaiting image/video approval, grouped per project + phase
const groups = {};
for (const j of items) {
  const f = j.fields;
  const st = f['Status Producție Scenă'];
  if (st === 'Așteaptă Aprobare Imagine' || st === 'Așteaptă Aprobare Video') {
    const pid = f['Project_ID'] || 'unknown';
    const phase = st.includes('Imagine') ? 'img' : 'vid';
    const key = pid + ':' + phase;
    groups[key] = groups[key] || { pid, phase, n: 0 };
    groups[key].n++;
  }
}
for (const g of Object.values(groups)) {
  if (mark('scene:' + g.pid + ':' + g.phase)) {
    const what = g.phase === 'img' ? 'imagini' : 'clipuri video';
    msgs.push('🖼️ **' + g.n + ' ' + what + ' așteaptă aprobarea ta**\n' + SITE + '/projects/' + g.pid);
  }
}

// Finished projects
for (const j of items) {
  const f = j.fields;
  if (f['Status General'] === 'Finalizat' && f['Nume Proiect']) {
    if (mark('done:' + j.id)) {
      msgs.push('✅ **Video finalizat:** ' + f['Nume Proiect'] + '\n' + (f['Link Video Final'] || SITE + '/projects/' + j.id));
    }
  }
}
return msgs.map(content => ({ json: { content, webhook: WEBHOOK } }));

